const dados = typeof $json.message === "string"
    ? JSON.parse($json.message)
    : $json.message;

return { json: dados };

// Timestamp e periodo no fuso de Sao Paulo. O PERIODO e o truque desta
// aplicacao: gravado agora, ele faz "ontem a noite" virar um WHERE comum
// na hora do chat, sem o LLM precisar fazer conta de data.
const agora = new Date().toLocaleString("sv-SE", {
  timeZone: "America/Sao_Paulo",
  hour12: false
});

const hora = Number(new Date().toLocaleString("en-US", {
  timeZone: "America/Sao_Paulo",
  hour: "numeric",
  hour12: false
}));

let periodo = "madrugada";
if (hora >= 6 && hora < 12) periodo = "manhã";
else if (hora >= 12 && hora < 18) periodo = "tarde";
else if (hora >= 18) periodo = "noite";

// A resposta da API esta no item atual; a predicao da borda ficou para tras,
// no no que leu o MQTT. E por isso que ela e buscada pelo nome do no.
const nuvem = $input.first().json.class;
const borda = $('Code (gera JSON)').first().json.predicao_borda;

return [{
  json: {
    predicao_borda: borda,
    predicao_nuvem: nuvem,
    concordam: borda === nuvem,
    timestamp_medicao: agora,
    periodo
  }
}];
